'use strict';

function $_(key, data, tags) {
    const i18n = (globalThis.I18NeverData || {});
    const lang = (globalThis.I18NeverLang || 'zh');
    const translations = i18n[key];
    if (!Array.isArray(data)) {
        tags = data;
        data = undefined;
    }
    if (translations) {
        const tagName = tags ? tags[lang] : 'default';
        const tag = translations.find((t) => t.name === tagName);
        {
            if (!tag) {
                throw new Error(`Cannot find the tag: "${tagName}" for key: "${key}" in language: "${lang}".`);
            }
        }
        key = tag.value || key;
    }
    return generateResult(key, data);
}
const valueRegexp = /\{([^}\s]+)}/g;
function generateResult(value, data) {
    if (data) {
        value = value.replace(valueRegexp, (nouse, variable) => {
            variable = data[variable];
            return !isNullOrUndefined(variable) ? variable.toString() : nouse;
        });
    }
    return value;
}
function isNullOrUndefined(value) {
    return value === null || value === undefined;
}

exports.$_ = $_;
